// Lesson: Production Runtimes (phase 14 / lesson 29)
// Go port of code/main.py. Go standard library only.
// Source: phases/14-agent-engineering/29-production-runtimes/docs/en.md
// Run: go run code/main.go

package main

import (
	"fmt"
	"strings"
)

func head(s string, n int) string {
	r := []rune(s)
	if len(r) > n {
		return string(r[:n])
	}
	return s
}

func agentFn(inputText string) []string {
	return []string{
		"parse: " + head(inputText, 40),
		"plan: 3-step plan",
		"step 1: search",
		"step 2: read",
		"final: answered " + head(inputText, 20),
	}
}

func requestResponse(inputText string) string {
	steps := agentFn(inputText)
	return steps[len(steps)-1]
}

func streaming(inputText string) <-chan string {
	out := make(chan string)
	go func() {
		defer close(out)
		for _, step := range agentFn(inputText) {
			out <- step
		}
	}()
	return out
}

type Job struct {
	Jid     string
	Payload string
	Attempt int
}

type Result struct {
	Key   string
	Value string
}

type QueueRuntime struct {
	queue   []*Job
	dlq     []*Job
	counter int
}

func (q *QueueRuntime) Enqueue(payload string) string {
	q.counter++
	jid := fmt.Sprintf("j%03d", q.counter)
	q.queue = append(q.queue, &Job{Jid: jid, Payload: payload})
	return jid
}

func (q *QueueRuntime) Worker(failPolicy func(*Job) bool) []Result {
	var results []Result
	for len(q.queue) > 0 {
		job := q.queue[0]
		q.queue = q.queue[1:]
		job.Attempt++
		if failPolicy(job) && job.Attempt < 3 {
			q.queue = append(q.queue, job)
			results = append(results, Result{job.Jid, "retry"})
			continue
		}
		if failPolicy(job) {
			q.dlq = append(q.dlq, job)
			results = append(results, Result{job.Jid, "DLQ"})
			continue
		}
		steps := agentFn(job.Payload)
		results = append(results, Result{job.Jid, steps[len(steps)-1]})
	}
	return results
}

type EventBus struct {
	subscribers map[string][]func(string) string
}

func NewEventBus() *EventBus {
	return &EventBus{subscribers: map[string][]func(string) string{}}
}

func (b *EventBus) Subscribe(eventType string, handler func(string) string) {
	b.subscribers[eventType] = append(b.subscribers[eventType], handler)
}

func (b *EventBus) Publish(eventType, payload string) []Result {
	var results []Result
	for _, handler := range b.subscribers[eventType] {
		results = append(results, Result{eventType, handler(payload)})
	}
	return results
}

func main() {
	fmt.Println(strings.Repeat("=", 70))
	fmt.Println("PRODUCTION RUNTIME SHAPES: Phase 14, Lesson 29")
	fmt.Println(strings.Repeat("=", 70))

	fmt.Println("\n1. request-response (synchronous)")
	out := requestResponse("list project files")
	fmt.Printf("  result: %s\n", out)

	fmt.Println("\n2. streaming (generator)")
	for step := range streaming("review this PR") {
		fmt.Printf("  chunk: %s\n", step)
	}

	fmt.Println("\n3. queue-based (with retry and DLQ)")
	rt := &QueueRuntime{}
	rt.Enqueue("long job A")
	rt.Enqueue("long job B")
	rt.Enqueue("long job C")

	failB := func(job *Job) bool {
		return job.Payload == "long job B"
	}

	for _, r := range rt.Worker(failB) {
		fmt.Printf("  %s: %s\n", r.Key, r.Value)
	}
	fmt.Printf("  queue: %d   dlq: %d\n", len(rt.queue), len(rt.dlq))

	fmt.Println("\n4. event-driven (subscriber pattern)")
	bus := NewEventBus()

	onPrOpened := func(payload string) string {
		return "ran checks on " + payload
	}
	onMemoryConsolidate := func(payload string) string {
		return "consolidated " + payload
	}

	bus.Subscribe("pr.opened", onPrOpened)
	bus.Subscribe("memory.consolidate", onMemoryConsolidate)

	for _, r := range bus.Publish("pr.opened", "#123 add feature") {
		fmt.Printf("  %s -> %s\n", r.Key, r.Value)
	}
	for _, r := range bus.Publish("memory.consolidate", "session_001") {
		fmt.Printf("  %s -> %s\n", r.Key, r.Value)
	}

	fmt.Println("\n5. scheduled (cron stand-in)")
	schedule := [][2]string{
		{"02:00", "memory.consolidate"},
		{"03:00", "eval.nightly"},
	}
	for _, s := range schedule {
		fmt.Printf("  %s: would fire %s\n", s[0], s[1])
	}

	fmt.Println()
	fmt.Println("same agent logic, four outer shells. pick by task shape.")
	fmt.Println("observability (Lesson 23/24) is load-bearing at every shape.")
}

// Lesson: Production Runtimes: Queue, Event, Cron (phase 14 / lesson 29)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/14-agent-engineering/29-production-runtimes/docs/en.md
// Run: npx tsx phases/14-agent-engineering/29-production-runtimes/code/main.ts

function agentFn(inputText: string): string[] {
  return [
    `parse: ${inputText.slice(0, 40)}`,
    "plan: 3-step plan",
    "step 1: search",
    "step 2: read",
    `final: answered ${inputText.slice(0, 20)}`,
  ];
}

function requestResponse(inputText: string): string {
  const steps = agentFn(inputText);
  return steps[steps.length - 1]!;
}

function* streaming(inputText: string): Generator<string> {
  for (const step of agentFn(inputText)) yield step;
}

class Job {
  attempt = 0;

  constructor(
    public jid: string,
    public payload: string,
  ) {}
}

class QueueRuntime {
  queue: Job[] = [];
  dlq: Job[] = [];
  failRate = 0;
  counter = 0;

  enqueue(payload: string): string {
    this.counter += 1;
    const jid = `j${String(this.counter).padStart(3, "0")}`;
    this.queue.push(new Job(jid, payload));
    return jid;
  }

  worker(failPolicy: (job: Job) => boolean): [string, string][] {
    const results: [string, string][] = [];
    while (this.queue.length > 0) {
      const job = this.queue.shift()!;
      job.attempt += 1;
      if (failPolicy(job) && job.attempt < 3) {
        this.queue.push(job);
        results.push([job.jid, "retry"]);
        continue;
      }
      if (failPolicy(job)) {
        this.dlq.push(job);
        results.push([job.jid, "DLQ"]);
        continue;
      }
      const steps = agentFn(job.payload);
      results.push([job.jid, steps[steps.length - 1]!]);
    }
    return results;
  }
}

class EventBus {
  subscribers = new Map<string, ((payload: string) => string)[]>();

  subscribe(eventType: string, handler: (payload: string) => string): void {
    let list = this.subscribers.get(eventType);
    if (list === undefined) {
      list = [];
      this.subscribers.set(eventType, list);
    }
    list.push(handler);
  }

  publish(eventType: string, payload: string): [string, string][] {
    return (this.subscribers.get(eventType) ?? []).map((handler) => [eventType, handler(payload)]);
  }
}

function main(): void {
  console.log("=".repeat(70));
  console.log("PRODUCTION RUNTIME SHAPES: Phase 14, Lesson 29");
  console.log("=".repeat(70));

  console.log("\n1. request-response (synchronous)");
  const out = requestResponse("list project files");
  console.log(`  result: ${out}`);

  console.log("\n2. streaming (generator)");
  for (const step of streaming("review this PR")) console.log(`  chunk: ${step}`);

  console.log("\n3. queue-based (with retry and DLQ)");
  const rt = new QueueRuntime();
  rt.enqueue("long job A");
  rt.enqueue("long job B");
  rt.enqueue("long job C");

  const failB = (job: Job): boolean => job.payload === "long job B";

  const results = rt.worker(failB);
  for (const [jid, status] of results) console.log(`  ${jid}: ${status}`);
  console.log(`  queue: ${rt.queue.length}   dlq: ${rt.dlq.length}`);

  console.log("\n4. event-driven (subscriber pattern)");
  const bus = new EventBus();

  const onPrOpened = (payload: string): string => `ran checks on ${payload}`;
  const onMemoryConsolidate = (payload: string): string => `consolidated ${payload}`;

  bus.subscribe("pr.opened", onPrOpened);
  bus.subscribe("memory.consolidate", onMemoryConsolidate);

  for (const [evt, res] of bus.publish("pr.opened", "#123 add feature")) console.log(`  ${evt} -> ${res}`);
  for (const [evt, res] of bus.publish("memory.consolidate", "session_001")) console.log(`  ${evt} -> ${res}`);

  console.log("\n5. scheduled (cron stand-in)");
  const schedule: [string, string][] = [
    ["02:00", "memory.consolidate"],
    ["03:00", "eval.nightly"],
  ];
  for (const [when, event] of schedule) console.log(`  ${when}: would fire ${event}`);

  console.log();
  console.log("same agent logic, four outer shells. pick by task shape.");
  console.log("observability (Lesson 23/24) is load-bearing at every shape.");
}

main();
